function IdolLive3D_Camera:Start()
    KTool.SetActive(self.controller.gameObject, true);    
    -- must after Awake()
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()
    assert( self.mainCamera )
end



function IdolLive3D_Camera:Init( main_ )

    assert( self.freeVCam and self.vcam2 and self.rawPoint and self.freeCameraMotion )

    self.idolLive3D_Main = main_
    self.baseJson = self.idolLive3D_Main.baseJson

    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [Constants.EventNames.Live3DIsInTimelineState]       = Bind(self, self.SwitchNavigatorBarBackBtn),
        [IdolLive3D_States.EventFreeCameraFreeze]           = Bind(self, self._SwitchToFreezeState),
        [IdolLive3D_States.EventMoveTo]                     = Bind(self, self.DoEventMoveTo),
        [IdolLive3D_States.EventGetFreeCameraSpatialParams] = Bind(self, self.DoEventGetFreeCameraSpatialParams),
        [IdolLive3D_States.EventSmlPackageInitFreeze]       = Bind(self, self.DoEventSmlPackageInitFreeze),
    })

    IdolLive3D_States.isPlayingTimeline = false

    -- =================
    local idle_100 = self.baseJson:Get_Idle_100()
    local idle_200 = self.baseJson:Get_Idle_200()

    self.idolLive3D_FreeCameraTrackNodeParamsManager_100 = IdolLive3D_FreeCameraTrackNodeParamsManager.New(idle_100.freeTrackJsonFileName, idle_100.freeTrackJson ) 
    self.idolLive3D_FreeCameraTrackNodeParamsManager_200 = IdolLive3D_FreeCameraTrackNodeParamsManager.New(idle_200.freeTrackJsonFileName, idle_200.freeTrackJson ) 

    -- =================
    ---@type IdolLive3D_FreeCameraMgr
    self.freeCameraMgr = IdolLive3D_FreeCameraMgr.New( self, self.baseJson, self.freeCameraMotion, self.freeVCam, self.vcam2 )

    ---
    self:InitCameraMode_Free()

    --
    self.isInit = true
end



function IdolLive3D_Camera:BindInput( idolLive3D_Input_ ) 
    assert( isNotNull(idolLive3D_Input_) )

    idolLive3D_Input_:Add_OnSwipeCallBack( function(gesture_)
        self:OnSwipe(gesture_)
    end )

    idolLive3D_Input_:Add_OnPinchCallBack( function(deltaPinch_)
        self:OnPinch(deltaPinch_)
    end )

    self.isBindInput = true
end


