function IdolLive3D_Camera:OnDestroy()

    if isNotNull(self.freeCameraMgr) then 
        self.freeCameraMgr:Delete()
    end

    if isNotNull(self.idolLive3D_FreeCameraTrackNodeParamsManager_100) then
        self.idolLive3D_FreeCameraTrackNodeParamsManager_100:Delete() 
    end

    if isNotNull(self.idolLive3D_FreeCameraTrackNodeParamsManager_200) then
        self.idolLive3D_FreeCameraTrackNodeParamsManager_200:Delete() 
    end

    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    IdolLive3D_States.isPlayingTimeline = false

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil
    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = nil
    IdolLive3D_Utils.StopCoroutine(self.co_3)
    self.co_3 = nil
    IdolLive3D_Utils.StopCoroutine(self.co_4)
    self.co_4 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


