function IdolLive3D_Camera:OnSwitchIdle(idleType)
    --printError("camera OnSwitchIdle")

    local DoSwitch = function( idleJson_, freeCameraTrackNodeParamsManager_ )
        if idleJson_.freeCameraMode == IdolLive3D_States.FreeCameraMode.PosFree then 
            self.freeCameraMgr:SwitchFreeCamera_PosFree( idleJson_.freeTrackCenterPos, idleJson_.freeCameraActiveSpatialRange, idleJson_.initCameraSpatialParams.to, freeCameraTrackNodeParamsManager_ )
        else 
            self.freeCameraMgr:SwitchFreeCamera_PosLocked( idleJson_.posLockedCameraParams )
        end
    end

    -- ===
    local idle_100 = self.baseJson:Get_Idle_100()
    local idle_200 = self.baseJson:Get_Idle_200()

    if idleType == IdolLive3D_States.IdleType.Type_100 then 
        DoSwitch(idle_100, self.idolLive3D_FreeCameraTrackNodeParamsManager_100)
    elseif idleType == IdolLive3D_States.IdleType.Type_200 then 
        DoSwitch(idle_200, self.idolLive3D_FreeCameraTrackNodeParamsManager_200)
    else 
        printError("参数异常: " .. tostring(idleType))
    end 
end




function IdolLive3D_Camera:SelfUpdate()
    if self.isInit ~= true or self.isBindInput ~= true then 
        return
    end 

    --print("cameraMode = " .. tostring(self.cameraMode))

    --- debug:
    if IdolLive3D_Utils.IsEditorPlatform() then

        -- if Input.GetKeyDown(KeyCode.R) then 
        --     local brain = IdolLive3D_Utils.GetCameraBrain()
        --     local vCam = brain.ActiveVirtualCamera
        --     local activeCamTF = (isNotNull(vCam) and isNotNull(vCam.VirtualCameraGameObject)) and vCam.VirtualCameraGameObject.transform or nil
        --     print( "cam = " .. tostring( activeCamTF.name ) )
        -- end

        -- if Input.GetKeyDown(KeyCode.Q) then 
        --     self.freeCameraMgr:SetFreeCameraMode( FreeCameraMode.PosFree )
        -- elseif Input.GetKeyDown(KeyCode.E) then 
        --     self.freeCameraMgr:SetFreeCameraMode( FreeCameraMode.PosLocked )
        --     self.freeCameraMgr:SetImmediately( {pos = Vector3(-1.74, 1.4, 1.5), lookDir = Vector3(0,0,1) } )
        -- end
    end


    if self.cameraMode == IdolLive3D_States.CameraMode.FreeManual  then 
        self.freeCameraMgr:SelfUpdate()

    elseif self.cameraMode == IdolLive3D_States.CameraMode.FreeAuto  then 

        if self.timelineCameraBlendMode == IdolLive3D_States.TimelineCameraBlendMode.FreeTrackRotate then 
            local r = self:FreeAutoUpdate()
            if r == nil then 
                if type(self.freeAutoEndCB) == "function" then 
                    self.freeAutoEndCB()
                    self.freeAutoEndCB = nil -- 只调用一次
                end 
                --printError("FreeAuto 结束")
            else 
                self.freeCameraMgr:SetSmooth(r)
                self.freeCameraMgr:SelfUpdate()
            end 
        else 
            -- SimpleBlend 模式下啥也不做, 干等
        end 

    elseif self.cameraMode == IdolLive3D_States.CameraMode.Freeze  then 
        -- 啥也不做

    elseif self.cameraMode == IdolLive3D_States.CameraMode.Timeline  then
        if IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline == false then 
            self.freeCameraMgr:SelfUpdate() 
        end 

    else 
    end 

    
    if      self.cameraMode == IdolLive3D_States.CameraMode.FreeManual  
        or  self.cameraMode == IdolLive3D_States.CameraMode.FreeAuto
        or  (self.cameraMode == IdolLive3D_States.CameraMode.Timeline and IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline == false)
    then 
        local params = self:GetFreeCameraSpatialParams()
        -- todo: debug: 打印 三个 参数:
        local textDebug = self.idolLive3D_Main.idolLive3D_TextDebugEnv
        if isNotNull(textDebug) then     
            textDebug:SetText( 1,  string.format("%.2f",  params.yaw ))
            textDebug:SetText( 2,  string.format("%.2f",  params.pitch ))
            textDebug:SetText( 3,  string.format("%.2f",  params.zoom )) 
        else 
            printError("textDebug is  null")
        end 
    end
end


