function IdolLive3D_Camera:InitCameraMode_Free( )
    --printError("InitCameraMode_Free")
    self.cameraMode = IdolLive3D_States.CameraMode.FreeManual
    self:SetCachedTimelineVCam( nil )
    self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.High )
end




function IdolLive3D_Camera:SetCachedTimelineVCam( vcam_ ) 
    
    if isNull(self.cachedTimelineVCam) and isNotNull(vcam_) then 
        --printError("timeline 锁 相机")
        IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline = true
    elseif isNotNull(self.cachedTimelineVCam) and isNull(vcam_) then 
        --printError("timeline 解锁 相机")
        IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline = false
    end
    self.cachedTimelineVCam = vcam_
end 


function IdolLive3D_Camera:SwitchToCameraMode_FreeManual( blendTime_ )
    if self.isInit ~= true  then  
        return
    end
    

    if self.cameraMode == IdolLive3D_States.CameraMode.FreeManual then 
        printError( "cameraMode 已经是 freeManual 了, 啥也不做" )

    elseif self.cameraMode == IdolLive3D_States.CameraMode.Freeze then
        self.cameraMode = IdolLive3D_States.CameraMode.FreeManual

    elseif self.cameraMode == IdolLive3D_States.CameraMode.FreeAuto then
        self.cameraMode = IdolLive3D_States.CameraMode.FreeManual

    elseif self.cameraMode == IdolLive3D_States.CameraMode.Timeline then

        Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, false)
        IdolLive3D_States.isPlayingTimeline = false

        ---
        IdolLive3D_Utils.StopCoroutine(self.co_1)
        self.co_1 = cs_coroutine.start(function()

            if isNotNull(self.cachedTimelineVCam) then 

                local finishedFreeCameraSpatialParams = nil
                if isNotNull(self.cachedTimelineInteractiveState) then
                    if isTable( self.cachedTimelineInteractiveState.finishedFreeCameraSpatialParams ) then 
                        finishedFreeCameraSpatialParams = self.cachedTimelineInteractiveState.finishedFreeCameraSpatialParams
                    end                
                else
                    printError("异常, cachedTimelineInteractiveState 为空")
                end

                -- 基于旧vcam位置, 修正 freeVCam 机位;
                self.freeCameraMgr:FreeCameraCloseToTgtPos( self.cachedTimelineVCam.transform.position, finishedFreeCameraSpatialParams )     
                -- 固定机位自由相机 清空旋转值:
                self.freeCameraMgr:PosLockedCameraResetImmediately()       
        
                self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.High )
                self.cachedTimelineVCam.Priority = IdolLive3D_States.VCamPriority.Low

                -- 等待 timelineVCam -> freeVCam 过度结束
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds( checkNumber(blendTime_) ))
                
                -- 等完之后再设置, 确保在相机切换阶段, 玩家依然无法操纵 自由轨道相机
                self:SetCachedTimelineVCam( nil )
            else 
                -- 说明最后一个 clip 没有 vcam, 无需相机切换操作;
            end
    
            self.cameraMode = IdolLive3D_States.CameraMode.FreeManual
        end) 
    else
        printError("cameraMode 数据异常")
    end
end



-- cut mode
function IdolLive3D_Camera:SwitchToCameraMode_Timeline( timelineVCam_, interactiveState_, isSettedEvent_ )
    if self.cameraMode == IdolLive3D_States.CameraMode.Timeline then 
        printError( "cameraMode 已经是 timeline 了, 啥也不做" )
        return
    end

    self:SetCachedTimelineVCam( timelineVCam_ ) -- maybe nil

    if isNotNull(self.cachedTimelineVCam) then
        self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.Low )
        self.cachedTimelineVCam.Priority = IdolLive3D_States.VCamPriority.High
    end

    self.cameraMode = IdolLive3D_States.CameraMode.Timeline

    self.cachedTimelineInteractiveState = interactiveState_

    -- 有些流程中已经提前设置了 event, 在此就不要重复了
    if isSettedEvent_ ~= true then 
        -- 进入 timeline state 内:
        Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, true)
        IdolLive3D_States.isPlayingTimeline = true
    end 
end


---@param cameraSpatialParams_ IdolLive3D_FreeCameraSpatialParams @ 本次 自由轨道相机 运动的终点
---@param freeAutoMoveMode_ number  @ enum
---@param time_ number      @ 本次运动的 时长
---@param closeThreshold_ number @ 靠多近时停止运动
---@param endCB_ function   @ 本次运动结束后的 cb, 必须要设置 (否则无法正确回到别的 cameraMode)
function IdolLive3D_Camera:SwitchToCameraMode_FreeAuto( cameraSpatialParams_, freeAutoMoveMode_, time_, closeThreshold_, endCB_ )
    if self.isInit ~= true  then  
        return
    end 
    if self.cameraMode == IdolLive3D_States.CameraMode.FreeAuto then 
        printError( "cameraMode 已经是 freeAuto 了, 啥也不做" )
        return
    end
    if type(endCB_) ~= "function" then 
        printError("必须设置参数 endCB_ ")
        return
    end 

    if self.cameraMode == IdolLive3D_States.CameraMode.Timeline then 
        -- 不在 timeline state 内:
        Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, false)
    end
    IdolLive3D_States.isPlayingTimeline = false


    self.freeAutoEndCB = endCB_
    self.timelineCameraBlendMode = IdolLive3D_States.TimelineCameraBlendMode.FreeTrackRotate
    self.freeAutoMoveMode = freeAutoMoveMode_ -- 仅当 self.timelineCameraBlendMode 为 FreeTrackRotate 时, 才用到此数据;

    self.freeAutoTgtCameraSpatialParams = cameraSpatialParams_
    
    self.freeAutoCloseThreshold = Mathf.Max( 0.0001, type(closeThreshold_) == "number" and closeThreshold_ or 0.01)

    self.freeAutoSpeed = {}
    self.freeAutoSpeed.yaw = 0
    self.freeAutoSpeed.pitch = 0
    self.freeAutoSpeed.zoom = 0

    local currentParams = self:GetFreeCameraSpatialParams()
    self.freeAutoMaxSpeed = {}
    self.freeAutoMaxSpeed.yaw = Mathf.Abs( Mathf.DeltaAngle( currentParams.yaw, cameraSpatialParams_.yaw ) / time_ ) -- !! Must Positive
    self.freeAutoMaxSpeed.pitch = Mathf.Abs( currentParams.pitch - cameraSpatialParams_.pitch ) / time_
    self.freeAutoMaxSpeed.zoom = Mathf.Abs( currentParams.zoom - cameraSpatialParams_.zoom ) / time_
    --
    self.cameraMode = IdolLive3D_States.CameraMode.FreeAuto
end


-- !! 这是目前超疼指定的模式, 主要用它
-- 先进 FreeAuto, 让 freeTrack vcam 简单 blend 到 timeline vcam, 然后自动进入 timeline 模式:
---@param timelineStateEnv_ table @ lua env
---@param interactiveState_ table
---@param blendTime_ number @ 允许调用者设置 blend time
function IdolLive3D_Camera:SwitchToCameraMode_FirstToFreeAuto_ThenToTimeLine( timelineStateEnv_, interactiveState_, blendTime_ )
    if self.isInit ~= true  then  
        return
    end 
    if self.cameraMode == IdolLive3D_States.CameraMode.FreeAuto then 
        printError( "cameraMode 已经是 freeAuto 了, 啥也不做" )
        return
    end
    ---
    -- 提前进入  timeline state 内:
    Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, true)
    IdolLive3D_States.isPlayingTimeline = true

    IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline = false

    ---
    local timelineVCam = timelineStateEnv_:GetVCam() -- maybe nil
    if type(blendTime_) ~= "number" then 
        blendTime_ = Mathf.Max( 0.0, Mathf.Abs( checkNumber(interactiveState_.easeInBlendTime) ))
    end 

    -- 提前立刻播放 timeline, 确保 timeline相机 进入正确状态;
    timelineStateEnv_:Play()

    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = cs_coroutine.start(function()

        if isNotNull(timelineVCam) then
            -- 说明第一个 clip 带有 vcam 时:

            -- 强制等待一帧, 确保 timeline相机 进入正确状态, 以便后面能正确 blend:
            coroutine.yield(Yielders.EndOfFrame)

            IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, blendTime_ )

            self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.Low )
            timelineVCam.Priority = IdolLive3D_States.VCamPriority.High
            -- 屏蔽用户输入
            self.timelineCameraBlendMode = IdolLive3D_States.TimelineCameraBlendMode.SimpleBlend
            self.cameraMode = IdolLive3D_States.CameraMode.FreeAuto 

            if blendTime_ > 0.0 then
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds( blendTime_  ))
            end
        else 
            -- 说明第一个 clip 没有 vcam;
        end

        self:SwitchToCameraMode_Timeline( timelineVCam, interactiveState_, true )
    end)
end




-- 当前本来就在 Timeline, 调用本函数播放下一个 timeline
---@param initFreeCameraSpatialParams_ table | nil
function IdolLive3D_Camera:ToNextTimeline( timelineStateEnv_, blendTime_, initFreeCameraSpatialParams_ )
    if self.isInit ~= true  then  
        return
    end 
    if self.cameraMode ~= IdolLive3D_States.CameraMode.Timeline then 
        printError( "只能从一个 timeline 进入下一个 timeline 时才能调用本函数" )
        return
    end
    ---
    local newTimelineVCam = timelineStateEnv_:GetVCam() -- maybe nil

    -- 提前立刻播放 timeline, 确保 timeline相机 进入正确状态;
    timelineStateEnv_:Play()


    if type(blendTime_) ~= "number" then 
        blendTime_ = 0.0
    end
    IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, blendTime_ )

    IdolLive3D_Utils.StopCoroutine(self.co_4)
    self.co_4 = cs_coroutine.start(function()

        if isNotNull(self.cachedTimelineVCam) then
            if isNotNull(newTimelineVCam) then 
                -- ===== 有vcam -> 有vcam: =====
                self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.Low )
                self.cachedTimelineVCam.Priority = IdolLive3D_States.VCamPriority.Low
                newTimelineVCam.Priority = IdolLive3D_States.VCamPriority.High
            else 
                -- ===== 有vcam -> 无vcam: =====
                self.cachedTimelineVCam.Priority = IdolLive3D_States.VCamPriority.Low

                -- 基于旧vcam位置, 修正 freeVCam 机位;
                self.freeCameraMgr:FreeCameraCloseToTgtPos( self.cachedTimelineVCam.transform.position, initFreeCameraSpatialParams_ )     
                -- 固定机位自由相机 清空旋转值:
                self.freeCameraMgr:PosLockedCameraResetImmediately()       
                self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.High )
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds( checkNumber(blendTime_) ))
            end 
        else 
            if isNotNull(newTimelineVCam) then 
                -- ===== 无vcam -> 有vcam: =====
                self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.Low )
                newTimelineVCam.Priority = IdolLive3D_States.VCamPriority.High
            else 
                -- ===== 无vcam -> 无vcam: =====
                self.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.High )
            end 
        end 

        self:SetCachedTimelineVCam( newTimelineVCam )

    end)
    
end



function IdolLive3D_Camera:SwitchToCameraMode_Freeze()
    if self.isInit ~= true  then  
        return
    end 
    if self.cameraMode == IdolLive3D_States.CameraMode.Freeze then 
        printError( "cameraMode 已经是 Freeze 了, 啥也不做" )
        return
    end


    if self.cameraMode == IdolLive3D_States.CameraMode.Timeline then 
        -- 不在 timeline state 内:
        Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, false)
    end
    IdolLive3D_States.isPlayingTimeline = false

    self.cameraMode = IdolLive3D_States.CameraMode.Freeze
end



-- ======================== freeCameraSpatialParams ================================


-- 通过参数可返回 raw/smooth 两个版本的数据:
---@param isRaw_ boolean or nil
---@return IdolLive3D_FreeCameraSpatialParams
function IdolLive3D_Camera:GetFreeCameraSpatialParams( isRaw_ )

    return IdolLive3D_FreeCameraSpatialParams.New(
        self.freeCameraMgr:GetYaw(isRaw_),    -- 相机在角色的哪个方位, [0,360], 在角色正前方为 0/360, 在角色右侧为 90, 后方为 180, 左侧为 270
        self.freeCameraMgr:GetPitchT(isRaw_), -- pitch t 值, [0,1] 表示相机在 pitch 轨道上的位置; 通常 上端为 0, 下端为 1
        self.freeCameraMgr:GetZoomT(isRaw_)   -- zoom t 值, [0,1] 近端为 0, 远端为 1
    )
end



-- ========================= Input ===============================

function IdolLive3D_Camera:OnSwipe( gesture_ )
    -- 当 idol 场景存在且为非激活, 此时要屏蔽输入
    if self.isInit ~= true or self.idolLive3D_Main:IsInit() ~= true then 
        return
    end

    if self.cameraMode ~= IdolLive3D_States.CameraMode.FreeManual and self.cameraMode ~= IdolLive3D_States.CameraMode.Timeline then 
        return
    end 

    if self.cameraMode == IdolLive3D_States.CameraMode.Timeline and IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline == true then 
        return
    end 
    
    if IdolLive3D_States.isForbidPlayerSwipeAndPinch == true then 
        return
    end 

    local swipeVec = gesture_.swipeVector  
    local retateW = 0.08
    local yawVal    =  swipeVec.x * retateW
    local pitchVal  = -swipeVec.y * retateW
    self.freeCameraMgr:YawAndPitchByDelta( yawVal, pitchVal )
end 



function IdolLive3D_Camera:OnPinch( deltaPinch_ )
    -- 当 idol 场景存在且为非激活, 此时要屏蔽输入
    if self.isInit ~= true or self.idolLive3D_Main:IsInit() ~= true  then 
        return
    end 

    if self.cameraMode ~= IdolLive3D_States.CameraMode.FreeManual and self.cameraMode ~= IdolLive3D_States.CameraMode.Timeline then 
        return
    end 

    if self.cameraMode == IdolLive3D_States.CameraMode.Timeline and IdolLive3D_States.isForbidPlayerSwipeAndPinchInTimeline == true then 
        return
    end 

    if IdolLive3D_States.isForbidPlayerSwipeAndPinch == true then 
        return
    end 
    --print("koko- Pinch: " .. tostring(deltaPinch_) )
    self.freeCameraMgr:ZoomByDelta( deltaPinch_ )
end 



-- ========================= FreeAuto  ===============================


---@return IdolLive3D_FreeCameraSpatialParams or nil
function IdolLive3D_Camera:FreeAutoUpdate()
    if self.timelineCameraBlendMode ~= IdolLive3D_States.TimelineCameraBlendMode.FreeTrackRotate then 
        printError(" 数据异常")
        return nil
    end 
    ---
    local currentParams = self:GetFreeCameraSpatialParams(true)
    local currentSmoothParams = self:GetFreeCameraSpatialParams(false) -- 专门用来检查运动是否到位了

    -- close enough:
    local closeThreshold = self.freeAutoCloseThreshold
    if      
            IdolLive3D_Utils.CloseEnough( currentSmoothParams.yaw, self.freeAutoTgtCameraSpatialParams.yaw, closeThreshold )
        and IdolLive3D_Utils.CloseEnough( currentSmoothParams.pitch, self.freeAutoTgtCameraSpatialParams.pitch, closeThreshold )
        and IdolLive3D_Utils.CloseEnough( currentSmoothParams.zoom, self.freeAutoTgtCameraSpatialParams.zoom, closeThreshold )
    then 
        --printError("足够接近, 正式结束")
        return nil
    end 

    if self.freeAutoMoveMode == IdolLive3D_States.FreeAutoMoveMode.Linear then 
        local ret = IdolLive3D_FreeCameraSpatialParams.New(
            Mathf.MoveTowardsAngle( currentParams.yaw, self.freeAutoTgtCameraSpatialParams.yaw, Time.deltaTime * self.freeAutoMaxSpeed.yaw ),
            Mathf.MoveTowards( currentParams.pitch, self.freeAutoTgtCameraSpatialParams.pitch, Time.deltaTime * self.freeAutoMaxSpeed.pitch ),
            Mathf.MoveTowards( currentParams.zoom, self.freeAutoTgtCameraSpatialParams.zoom, Time.deltaTime * self.freeAutoMaxSpeed.zoom )
        )
        return ret

    else 
        local smoothTime = 0.05 -- 手调的参数, 没有暴露给美术编辑器
        local speedW = 10       -- 手调的参数, 没有暴露给美术编辑器

        local ret = IdolLive3D_FreeCameraSpatialParams.New(
            Mathf.SmoothDampAngle( currentParams.yaw, self.freeAutoTgtCameraSpatialParams.yaw, self.freeAutoSpeed.yaw, smoothTime, self.freeAutoMaxSpeed.yaw * speedW, Time.deltaTime ),
            Mathf.SmoothDamp(      currentParams.pitch, self.freeAutoTgtCameraSpatialParams.pitch, self.freeAutoSpeed.pitch, smoothTime, self.freeAutoMaxSpeed.pitch * speedW, Time.deltaTime ),
            Mathf.SmoothDamp(      currentParams.zoom, self.freeAutoTgtCameraSpatialParams.zoom, self.freeAutoSpeed.zoom, smoothTime, self.freeAutoMaxSpeed.zoom * speedW, Time.deltaTime )
        )
        return ret
    end
end



function IdolLive3D_Camera:FindClosestFreeCameraTrackNodeParams(pos_)
    return self.freeCameraMgr:FindClosestTrackNodeParams(pos_)
end





function IdolLive3D_Camera:SwitchNavigatorBarBackBtn( isInTimeline_ ) 
    --printError("isInTimeline_ = " .. tostring(isInTimeline_) )
    if type(isInTimeline_) ~= "boolean" then 
        printError("参数 isInTimeline_ 异常")
        isInTimeline_ = false
    end 
    if IdolLive3D_States.isHideUIInTimelineState ~= true then
        return
    end
    ---
    IdolLive3D_Utils.ShowHideNavigatorBarBackBtn( not checkBool(isInTimeline_) )
end 



-- 冻结/释放 自由相机操作权, 让画面固定在某个机位
function IdolLive3D_Camera:_SwitchToFreezeState( params_ )

    if params_.isFreeze == true then 

        if isTable(params_.tgtFreeCameraParams) then 
            -- 此处就不对 params_.tgtFreeCameraParams 内的数据做检查了, 全仰赖 IdolLive3D_States.EnterFreeze() 里的检查;
            local tp = params_.tgtFreeCameraParams
            self:SwitchToCameraMode_FreeAuto(
                tp.tgtCameraSpatialParams,
                IdolLive3D_States.FreeAutoMoveMode.SmoothDamp,
                tp.enterTime,
                tp.closeThreshold,
                function()
                    self:SwitchToCameraMode_Freeze()
                end
            )
        else 
            self:SwitchToCameraMode_Freeze()
        end 

    else 
        self:SwitchToCameraMode_FreeManual()
    end     
end




function IdolLive3D_Camera:DoEventMoveTo( params_ )
    if isTable(params_.tgtFreeCameraParams) then 
        -- 此处就不对 params_.tgtFreeCameraParams 内的数据做检查了, 全仰赖 IdolLive3D_States.EnterFreeze() 里的检查;
        local tp = params_.tgtFreeCameraParams
        self:SwitchToCameraMode_FreeAuto(
            tp.tgtCameraSpatialParams,
            IdolLive3D_States.FreeAutoMoveMode.SmoothDamp,
            tp.enterTime,
            tp.closeThreshold,
            function()
                self:SwitchToCameraMode_FreeManual( 0 )
            end
        )
    end 
end


function IdolLive3D_Camera:DoEventGetFreeCameraSpatialParams( retTable_ )
    retTable_.ret = self:GetFreeCameraSpatialParams()
end

return IdolLive3D_Camera
